import { sql } from 'drizzle-orm';
import {
  pgTable,
  varchar,
  text,
  timestamp,
  integer,
  decimal,
  boolean,
  pgEnum,
} from "drizzle-orm/pg-core";
import { createInsertSchema, createSelectSchema } from "drizzle-zod";
import { z } from "zod";

// Tour status enum
export const tourStatusEnum = pgEnum('tour_status', [
  'pending_approval',
  'active', 
  'ongoing',
  'completed',
  'declined',
  'for_revision',
  'for_reevaluation'
]);

// User role enum  
export const userRoleEnum = pgEnum('user_role', ['user', 'host', 'admin']);

// User status enum
export const userStatusEnum = pgEnum('user_status', ['active', 'suspended']);

// Article status enum
export const articleStatusEnum = pgEnum('article_status', ['published', 'draft', 'review']);

// Tours table for admin management
export const adminTours = pgTable("admin_tours", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  title: varchar("title", { length: 255 }).notNull(),
  description: text("description"),
  category: text("category").notNull(), // JSON array as text
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  currency: varchar("currency", { length: 3 }).default("PHP"),
  status: tourStatusEnum("status").default("pending_approval"),
  hostId: varchar("host_id").notNull(),
  hostName: varchar("host_name").notNull(),
  hostAvatar: varchar("host_avatar"),
  bookingsCount: integer("bookings_count").default(0),
  revenue: decimal("revenue", { precision: 12, scale: 2 }).default("0"),
  rating: decimal("rating", { precision: 2, scale: 1 }).default("0"),
  maxParticipants: integer("max_participants"),
  duration: varchar("duration"),
  location: varchar("location"),
  heroImage: varchar("hero_image"),
  featured: boolean("featured").default(false),
  startAt: timestamp("start_at"),
  endAt: timestamp("end_at"),
  adminNotes: text("admin_notes"), // For revision/decline reasons
  lastStatusChange: timestamp("last_status_change").defaultNow(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Admin users table
export const adminUsers = pgTable("admin_users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name", { length: 255 }).notNull(),
  email: varchar("email", { length: 255 }).unique().notNull(),
  avatar: varchar("avatar"),
  role: userRoleEnum("role").default("user"),
  status: userStatusEnum("status").default("active"),
  totalBookings: integer("total_bookings").default(0),
  totalSpent: decimal("total_spent", { precision: 12, scale: 2 }).default("0"),
  lastLoginAt: timestamp("last_login_at"),
  joinedAt: timestamp("joined_at").defaultNow(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Admin articles table
export const adminArticles = pgTable("admin_articles", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  title: varchar("title", { length: 255 }).notNull(),
  slug: varchar("slug", { length: 255 }).unique().notNull(),
  content: text("content"),
  excerpt: text("excerpt"),
  category: varchar("category", { length: 100 }).notNull(),
  tags: text("tags"), // JSON array as text
  author: varchar("author", { length: 255 }).notNull(),
  authorId: varchar("author_id"),
  status: articleStatusEnum("status").default("draft"),
  featuredImage: varchar("featured_image"),
  views: integer("views").default(0),
  likes: integer("likes").default(0),
  publishedAt: timestamp("published_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Admin bookings table for tracking
export const adminBookings = pgTable("admin_bookings", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  tourId: varchar("tour_id").notNull(),
  userId: varchar("user_id").notNull(),
  userName: varchar("user_name").notNull(),
  userEmail: varchar("user_email").notNull(),
  tourTitle: varchar("tour_title").notNull(),
  amount: decimal("amount", { precision: 10, scale: 2 }).notNull(),
  currency: varchar("currency", { length: 3 }).default("PHP"),
  status: varchar("status", { length: 50 }).default("pending"), // pending, confirmed, cancelled, completed
  participants: integer("participants").default(1),
  bookingDate: timestamp("booking_date").notNull(),
  travelDate: timestamp("travel_date"),
  notes: text("notes"),
  paymentStatus: varchar("payment_status", { length: 50 }).default("pending"),
  paymentId: varchar("payment_id"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Admin hosts table
export const adminHosts = pgTable("admin_hosts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").unique().notNull(),
  businessName: varchar("business_name"),
  description: text("description"),
  specialties: text("specialties"), // JSON array as text
  experience: varchar("experience"),
  location: varchar("location"),
  website: varchar("website"),
  socialMedia: text("social_media"), // JSON object as text
  verificationStatus: varchar("verification_status").default("pending"), // pending, verified, rejected
  documentsSubmitted: boolean("documents_submitted").default(false),
  rating: decimal("rating", { precision: 2, scale: 1 }).default("0"),
  totalTours: integer("total_tours").default(0),
  totalRevenue: decimal("total_revenue", { precision: 12, scale: 2 }).default("0"),
  commissionRate: decimal("commission_rate", { precision: 3, scale: 2 }).default("15.00"), // 15%
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Platform settings table
export const adminSettings = pgTable("admin_settings", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  key: varchar("key", { length: 255 }).unique().notNull(),
  value: text("value"),
  category: varchar("category", { length: 100 }).default("general"),
  description: text("description"),
  dataType: varchar("data_type", { length: 50 }).default("string"), // string, number, boolean, json
  isPublic: boolean("is_public").default(false),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Type exports
export type AdminTour = typeof adminTours.$inferSelect;
export type InsertAdminTour = typeof adminTours.$inferInsert;
export type AdminUser = typeof adminUsers.$inferSelect;
export type InsertAdminUser = typeof adminUsers.$inferInsert;
export type AdminArticle = typeof adminArticles.$inferSelect;
export type InsertAdminArticle = typeof adminArticles.$inferInsert;
export type AdminBooking = typeof adminBookings.$inferSelect;
export type InsertAdminBooking = typeof adminBookings.$inferInsert;
export type AdminHost = typeof adminHosts.$inferSelect;
export type InsertAdminHost = typeof adminHosts.$inferInsert;
export type AdminSetting = typeof adminSettings.$inferSelect;
export type InsertAdminSetting = typeof adminSettings.$inferInsert;

// Zod schemas
export const insertAdminTourSchema = createInsertSchema(adminTours);
export const selectAdminTourSchema = createSelectSchema(adminTours);

export const insertAdminUserSchema = createInsertSchema(adminUsers);
export const selectAdminUserSchema = createSelectSchema(adminUsers);

export const insertAdminArticleSchema = createInsertSchema(adminArticles);
export const selectAdminArticleSchema = createSelectSchema(adminArticles);

export const insertAdminBookingSchema = createInsertSchema(adminBookings);
export const selectAdminBookingSchema = createSelectSchema(adminBookings);

export const insertAdminHostSchema = createInsertSchema(adminHosts);
export const selectAdminHostSchema = createSelectSchema(adminHosts);

export const insertAdminSettingSchema = createInsertSchema(adminSettings);
export const selectAdminSettingSchema = createSelectSchema(adminSettings);

// Analytics types
export interface AdminAnalytics {
  totalTours: number;
  activeTours: number;
  totalUsers: number;
  activeUsers: number;
  totalHosts: number;
  verifiedHosts: number;
  totalBookings: number;
  monthlyRevenue: number;
  monthlyBookings: number;
  topCategories: Array<{category: string; count: number}>;
  recentActivity: Array<{
    type: 'tour' | 'user' | 'booking' | 'host';
    action: string;
    timestamp: string;
    details: string;
  }>;
}

// Tour management filters
export interface TourFilters {
  status?: 'active' | 'inactive' | 'pending' | 'all';
  category?: string;
  hostId?: string;
  featured?: boolean;
  dateRange?: {
    start: string;
    end: string;
  };
}

// User management filters  
export interface UserFilters {
  role?: 'user' | 'host' | 'admin' | 'all';
  status?: 'active' | 'suspended' | 'all';
  joinedAfter?: string;
  totalSpentMin?: number;
  totalBookingsMin?: number;
}

// Article management filters
export interface ArticleFilters {
  status?: 'published' | 'draft' | 'review' | 'all';
  category?: string;
  author?: string;
  dateRange?: {
    start: string;
    end: string;
  };
}

shared/chat-schema.ts.content:
import { sql } from 'drizzle-orm';
import {
  pgTable,
  varchar,
  text,
  timestamp,
  boolean,
  pgEnum,
  jsonb,
} from "drizzle-orm/pg-core";
import { createInsertSchema, createSelectSchema } from "drizzle-zod";
import { z } from "zod";

// Chat types
export const chatTypeEnum = pgEnum('chat_type', ['direct', 'group', 'trip', 'host_community']);
export const messageTypeEnum = pgEnum('message_type', ['text', 'image', 'file', 'system']);

// Chat rooms/groups
export const chatRooms = pgTable("chat_rooms", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name", { length: 255 }).notNull(),
  type: chatTypeEnum("type").notNull(),
  description: text("description"),
  avatar: varchar("avatar"),

  // Trip-specific fields
  tripId: varchar("trip_id"), // Reference to tour/trip
  hostId: varchar("host_id"), // Host who created/manages the chat

  // Settings
  isActive: boolean("is_active").default(true),
  maxParticipants: varchar("max_participants"), // JSON string for flexibility
  settings: jsonb("settings"), // Chat settings as JSON

  createdBy: varchar("created_by").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Chat participants/members
export const chatParticipants = pgTable("chat_participants", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  chatRoomId: varchar("chat_room_id").notNull(),
  userId: varchar("user_id").notNull(),

  // Participant role and status
  role: varchar("role", { length: 50 }).default("member"), // member, admin, host
  isActive: boolean("is_active").default(true),
  isMuted: boolean("is_muted").default(false),

  // Tracking
  joinedAt: timestamp("joined_at").defaultNow(),
  lastSeenAt: timestamp("last_seen_at"),
  leftAt: timestamp("left_at"),

  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Chat messages
export const chatMessages = pgTable("chat_messages", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  chatRoomId: varchar("chat_room_id").notNull(),
  senderId: varchar("sender_id").notNull(),
  senderName: varchar("sender_name").notNull(), // Cached for performance
  senderAvatar: varchar("sender_avatar"), // Cached for performance

  // Message content
  type: messageTypeEnum("type").default("text"),
  content: text("content").notNull(),
  attachments: jsonb("attachments"), // File attachments as JSON array
  metadata: jsonb("metadata"), // Additional data (reply info, etc.)

  // Message status
  isEdited: boolean("is_edited").default(false),
  isDeleted: boolean("is_deleted").default(false),
  editedAt: timestamp("edited_at"),

  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Message read receipts
export const messageReadReceipts = pgTable("message_read_receipts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  messageId: varchar("message_id").notNull(),
  userId: varchar("user_id").notNull(),
  readAt: timestamp("read_at").defaultNow(),
});

// Chat room stats (for performance)
export const chatRoomStats = pgTable("chat_room_stats", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  chatRoomId: varchar("chat_room_id").unique().notNull(),

  participantCount: varchar("participant_count").default("0"),
  messageCount: varchar("message_count").default("0"),
  lastMessageAt: timestamp("last_message_at"),
  lastMessageContent: text("last_message_content"), // Preview
  lastMessageSender: varchar("last_message_sender"),

  updatedAt: timestamp("updated_at").defaultNow(),
});

// Type exports
export type ChatRoom = typeof chatRooms.$inferSelect;
export type InsertChatRoom = typeof chatRooms.$inferInsert;
export type ChatParticipant = typeof chatParticipants.$inferSelect;
export type InsertChatParticipant = typeof chatParticipants.$inferInsert;
export type ChatMessage = typeof chatMessages.$inferSelect;
export type InsertChatMessage = typeof chatMessages.$inferInsert;
export type MessageReadReceipt = typeof messageReadReceipts.$inferSelect;
export type InsertMessageReadReceipt = typeof messageReadReceipts.$inferInsert;
export type ChatRoomStats = typeof chatRoomStats.$inferSelect;
export type InsertChatRoomStats = typeof chatRoomStats.$inferInsert;

// Zod schemas
export const insertChatRoomSchema = createInsertSchema(chatRooms);
export const selectChatRoomSchema = createSelectSchema(chatRooms);

export const insertChatParticipantSchema = createInsertSchema(chatParticipants);
export const selectChatParticipantSchema = createSelectSchema(chatParticipants);

export const insertChatMessageSchema = createInsertSchema(chatMessages);
export const selectChatMessageSchema = createSelectSchema(chatMessages);

// Extended types for API responses
export interface ChatRoomWithStats extends ChatRoom {
  stats: ChatRoomStats;
  participantCount: number;
  unreadCount: number;
  lastMessage?: {
    content: string;
    sender: string;
    timestamp: string;
  };
}

export interface ChatMessageWithSender extends ChatMessage {
  isOwnMessage: boolean;
  readBy?: string[]; // List of users who read the message
}

export interface ChatParticipantWithUser extends ChatParticipant {
  user: {
    name: string;
    email: string;
    avatar?: string;
  };
}

// Chat events for real-time functionality
export interface ChatEvent {
  type: 'message' | 'user_joined' | 'user_left' | 'typing' | 'read_receipt';
  chatRoomId: string;
  userId?: string;
  data: any;
  timestamp: string;
}

shared/schema.ts.content:
import { pgTable, text, serial, integer, boolean, decimal, timestamp, varchar, jsonb, pgEnum } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";
import { relations } from "drizzle-orm";

// User role enum
export const userRoleEnum = pgEnum('user_role', ['user', 'host', 'admin']);

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  username: text("username").notNull().unique(),
  password: text("password"),
  email: text("email"),
  firstName: text("first_name"),
  lastName: text("last_name"),
  phone: text("phone"),
  address: text("address"),
  city: text("city"),
  postalCode: text("postal_code"),
  country: text("country").default("Philippines"),
  googleId: text("google_id").unique(),
  facebookId: text("facebook_id").unique(),
  profileImage: text("profile_image"),
  authProvider: text("auth_provider").default("local"), // 'local', 'google', 'facebook'
  role: userRoleEnum("role").default("user"), // user, host, admin
  createdAt: timestamp("created_at").defaultNow(),
});

// Product Categories
export const categories = pgTable("categories", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  description: text("description"),
  image: text("image"),
  parentId: integer("parent_id"),
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
});

// Products
export const products = pgTable("products", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  description: text("description"),
  shortDescription: text("short_description"),
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  salePrice: decimal("sale_price", { precision: 10, scale: 2 }),
  sku: text("sku").unique(),
  stock: integer("stock").default(0),
  images: text("images").array(),
  categoryId: integer("category_id").references(() => categories.id),
  brand: text("brand"),
  weight: decimal("weight", { precision: 8, scale: 2 }),
  dimensions: text("dimensions"),
  colors: text("colors").array(),
  sizes: text("sizes").array(),
  materials: text("materials").array(),
  features: text("features").array(),
  isActive: boolean("is_active").default(true),
  isFeatured: boolean("is_featured").default(false),
  rating: decimal("rating", { precision: 3, scale: 2 }).default("0"),
  reviewCount: integer("review_count").default(0),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Product Variants (for different sizes/colors)
export const productVariants = pgTable("product_variants", {
  id: serial("id").primaryKey(),
  productId: integer("product_id").references(() => products.id),
  sku: text("sku").unique(),
  size: text("size"),
  color: text("color"),
  price: decimal("price", { precision: 10, scale: 2 }),
  stock: integer("stock").default(0),
  image: text("image"),
  isActive: boolean("is_active").default(true),
});

// Shopping Cart
export const cartItems = pgTable("cart_items", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").references(() => users.id),
  productId: integer("product_id").references(() => products.id),
  variantId: integer("variant_id").references(() => productVariants.id),
  quantity: integer("quantity").notNull().default(1),
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  createdAt: timestamp("created_at").defaultNow(),
});

// Orders
export const orders = pgTable("orders", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").references(() => users.id),
  orderNumber: text("order_number").notNull().unique(),
  status: text("status").notNull().default("pending"), // pending, processing, shipped, delivered, cancelled
  subtotal: decimal("subtotal", { precision: 10, scale: 2 }).notNull(),
  shippingFee: decimal("shipping_fee", { precision: 10, scale: 2 }).default("0"),
  tax: decimal("tax", { precision: 10, scale: 2 }).default("0"),
  total: decimal("total", { precision: 10, scale: 2 }).notNull(),
  currency: text("currency").default("PHP"),
  paymentMethod: text("payment_method"),
  paymentStatus: text("payment_status").default("pending"),
  paymentId: text("payment_id"),
  shippingAddress: jsonb("shipping_address"),
  billingAddress: jsonb("billing_address"),
  notes: text("notes"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Order Items
export const orderItems = pgTable("order_items", {
  id: serial("id").primaryKey(),
  orderId: integer("order_id").references(() => orders.id),
  productId: integer("product_id").references(() => products.id),
  variantId: integer("variant_id").references(() => productVariants.id),
  quantity: integer("quantity").notNull(),
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  total: decimal("total", { precision: 10, scale: 2 }).notNull(),
});

// Product Reviews
export const reviews = pgTable("reviews", {
  id: serial("id").primaryKey(),
  productId: integer("product_id").references(() => products.id),
  userId: integer("user_id").references(() => users.id),
  rating: integer("rating").notNull(),
  title: text("title"),
  comment: text("comment"),
  isVerified: boolean("is_verified").default(false),
  createdAt: timestamp("created_at").defaultNow(),
});

// Wishlist
export const wishlistItems = pgTable("wishlist_items", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").references(() => users.id),
  productId: integer("product_id").references(() => products.id),
  createdAt: timestamp("created_at").defaultNow(),
});

// Relations
export const usersRelations = relations(users, ({ many }) => ({
  cartItems: many(cartItems),
  orders: many(orders),
  reviews: many(reviews),
  wishlistItems: many(wishlistItems),
}));

export const categoriesRelations = relations(categories, ({ many, one }) => ({
  products: many(products),
  parent: one(categories, {
    fields: [categories.parentId],
    references: [categories.id],
  }),
  children: many(categories),
}));

export const productsRelations = relations(products, ({ one, many }) => ({
  category: one(categories, {
    fields: [products.categoryId],
    references: [categories.id],
  }),
  variants: many(productVariants),
  cartItems: many(cartItems),
  orderItems: many(orderItems),
  reviews: many(reviews),
  wishlistItems: many(wishlistItems),
}));

export const productVariantsRelations = relations(productVariants, ({ one, many }) => ({
  product: one(products, {
    fields: [productVariants.productId],
    references: [products.id],
  }),
  cartItems: many(cartItems),
  orderItems: many(orderItems),
}));

export const cartItemsRelations = relations(cartItems, ({ one }) => ({
  user: one(users, {
    fields: [cartItems.userId],
    references: [users.id],
  }),
  product: one(products, {
    fields: [cartItems.productId],
    references: [products.id],
  }),
  variant: one(productVariants, {
    fields: [cartItems.variantId],
    references: [productVariants.id],
  }),
}));

export const ordersRelations = relations(orders, ({ one, many }) => ({
  user: one(users, {
    fields: [orders.userId],
    references: [users.id],
  }),
  items: many(orderItems),
}));

export const orderItemsRelations = relations(orderItems, ({ one }) => ({
  order: one(orders, {
    fields: [orderItems.orderId],
    references: [orders.id],
  }),
  product: one(products, {
    fields: [orderItems.productId],
    references: [products.id],
  }),
  variant: one(productVariants, {
    fields: [orderItems.variantId],
    references: [productVariants.id],
  }),
}));

export const reviewsRelations = relations(reviews, ({ one }) => ({
  product: one(products, {
    fields: [reviews.productId],
    references: [products.id],
  }),
  user: one(users, {
    fields: [reviews.userId],
    references: [users.id],
  }),
}));

export const wishlistItemsRelations = relations(wishlistItems, ({ one }) => ({
  user: one(users, {
    fields: [wishlistItems.userId],
    references: [users.id],
  }),
  product: one(products, {
    fields: [wishlistItems.productId],
    references: [products.id],
  }),
}));

// Zod Schemas
export const insertUserSchema = createInsertSchema(users).pick({
  username: true,
  password: true,
  email: true,
  firstName: true,
  lastName: true,
  phone: true,
  address: true,
  city: true,
  postalCode: true,
  country: true,
  googleId: true,
  profileImage: true,
  authProvider: true,
});

export const insertCategorySchema = createInsertSchema(categories).omit({
  id: true,
  createdAt: true,
});

export const insertProductSchema = createInsertSchema(products).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertProductVariantSchema = createInsertSchema(productVariants).omit({
  id: true,
});

export const insertCartItemSchema = createInsertSchema(cartItems).omit({
  id: true,
  createdAt: true,
});

export const insertOrderSchema = createInsertSchema(orders).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertOrderItemSchema = createInsertSchema(orderItems).omit({
  id: true,
});

export const insertReviewSchema = createInsertSchema(reviews).omit({
  id: true,
  createdAt: true,
});

export const insertWishlistItemSchema = createInsertSchema(wishlistItems).omit({
  id: true,
  createdAt: true,
});

// Tours/Lakbay table
export const tours = pgTable("tours", {
  id: serial("id").primaryKey(),
  title: text("title").notNull(),
  description: text("description"),
  category: text("category").notNull(),
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  currency: text("currency").default("PHP"),
  hostName: text("host_name").notNull(),
  hostAvatar: text("host_avatar"),
  hostBio: text("host_bio"),
  maxParticipants: integer("max_participants").default(1),
  duration: text("duration"),
  location: text("location"),
  heroImage: text("hero_image"),
  featured: boolean("featured").default(false),
  status: text("status").default("pending"), // active, inactive, pending
  meetingPlace: text("meeting_place"),
  accommodation: jsonb("accommodation"), // {name, description}
  mapCenter: jsonb("map_center"), // {lat, lng}
  itinerary: jsonb("itinerary"), // array of daily activities
  trail: jsonb("trail"), // trail info for hiking tours

  // Tab content fields
  inclusions: text("inclusions").array(), // What's included
  thingsToBring: text("things_to_bring").array(), // Things to bring
  reminders: text("reminders").array(), // Important reminders
  cancellationPolicy: text("cancellation_policy"), // Cancellation terms

  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

export const insertTourSchema = createInsertSchema(tours).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

// Types
export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;
export type InsertCategory = z.infer<typeof insertCategorySchema>;
export type Category = typeof categories.$inferSelect;
export type InsertProduct = z.infer<typeof insertProductSchema>;
export type Product = typeof products.$inferSelect;
export type InsertProductVariant = z.infer<typeof insertProductVariantSchema>;
export type ProductVariant = typeof productVariants.$inferSelect;
export type InsertCartItem = z.infer<typeof insertCartItemSchema>;
export type CartItem = typeof cartItems.$inferSelect;
export type InsertOrder = z.infer<typeof insertOrderSchema>;
export type Order = typeof orders.$inferSelect;
export type InsertOrderItem = z.infer<typeof insertOrderItemSchema>;
export type OrderItem = typeof orderItems.$inferSelect;
export type InsertReview = z.infer<typeof insertReviewSchema>;
export type Review = typeof reviews.$inferSelect;
export type InsertWishlistItem = z.infer<typeof insertWishlistItemSchema>;
export type WishlistItem = typeof wishlistItems.$inferSelect;
export type InsertTour = z.infer<typeof insertTourSchema>;
export type Tour = typeof tours.$inferSelect;

// Tour status enum
export const tourStatusEnum = pgEnum('tour_status', ['active', 'inactive', 'pending']);

// User status enum
export const userStatusEnum = pgEnum('user_status', ['active', 'suspended']);

// Tours table for admin management
export const adminTours = pgTable("admin_tours", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  title: varchar("title", { length: 255 }).notNull(),
  description: text("description"),
  category: varchar("category", { length: 100 }).notNull(),
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  currency: varchar("currency", { length: 3 }).default("PHP"),
  status: tourStatusEnum("status").default("pending"),
  hostId: varchar("host_id").notNull(),
  hostName: varchar("host_name").notNull(),
  hostAvatar: varchar("host_avatar"),
  bookingsCount: integer("bookings_count").default(0),
  revenue: decimal("revenue", { precision: 12, scale: 2 }).default("0"),
  rating: decimal("rating", { precision: 2, scale: 1 }).default("0"),
  maxParticipants: integer("max_participants"),
  duration: varchar("duration"),
  location: varchar("location"),
  heroImage: varchar("hero_image"),
  featured: boolean("featured").default(false),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Admin users table
export const adminUsers = pgTable("admin_users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name", { length: 255 }).notNull(),
  email: varchar("email", { length: 255 }).unique().notNull(),
  avatar: varchar("avatar"),
  role: userRoleEnum("role").default("user"),
  status: userStatusEnum("status").default("active"),
  totalBookings: integer("total_bookings").default(0),
  totalSpent: decimal("total_spent", { precision: 12, scale: 2 }).default("0"),
  lastLoginAt: timestamp("last_login_at"),
  joinedAt: timestamp("joined_at").defaultNow(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Admin bookings table for tracking
export const adminBookings = pgTable("admin_bookings", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  tourId: varchar("tour_id").notNull(),
  userId: varchar("user_id").notNull(),
  userName: varchar("user_name").notNull(),
  userEmail: varchar("user_email").notNull(),
  tourTitle: varchar("tour_title").notNull(),
  amount: decimal("amount", { precision: 10, scale: 2 }).notNull(),
  currency: varchar("currency", { length: 3 }).default("PHP"),
  status: varchar("status", { length: 50 }).default("pending"),
  participants: integer("participants").default(1),
  bookingDate: timestamp("booking_date").notNull(),
  travelDate: timestamp("travel_date"),
  notes: text("notes"),
  paymentStatus: varchar("payment_status", { length: 50 }).default("pending"),
  paymentId: varchar("payment_id"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Admin hosts table
export const adminHosts = pgTable("admin_hosts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").unique().notNull(),
  businessName: varchar("business_name"),
  description: text("description"),
  specialties: text("specialties"),
  experience: varchar("experience"),
  location: varchar("location"),
  website: varchar("website"),
  socialMedia: text("social_media"),
  verificationStatus: varchar("verification_status").default("pending"),
  documentsSubmitted: boolean("documents_submitted").default(false),
  rating: decimal("rating", { precision: 2, scale: 1 }).default("0"),
  totalTours: integer("total_tours").default(0),
  totalRevenue: decimal("total_revenue", { precision: 12, scale: 2 }).default("0"),
  commissionRate: decimal("commission_rate", { precision: 3, scale: 2 }).default("15.00"),
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Admin schema types
export type AdminTour = typeof adminTours.$inferSelect;
export type InsertAdminTour = typeof adminTours.$inferInsert;
export type AdminUser = typeof adminUsers.$inferSelect;
export type InsertAdminUser = typeof adminUsers.$inferInsert;
export type AdminBooking = typeof adminBookings.$inferSelect;
export type InsertAdminBooking = typeof adminBookings.$inferInsert;
export type AdminHost = typeof adminHosts.$inferSelect;
export type InsertAdminHost = typeof adminHosts.$inferInsert;

shared/shop-schema.ts.content:
import { sql } from 'drizzle-orm';
import {
  pgTable,
  varchar,
  text,
  integer,
  decimal,
  timestamp,
  jsonb,
  boolean,
} from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// Products table
export const products = pgTable("products", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  description: text("description"),
  category: varchar("category").notNull(), // electronics, clothing, home, books, etc.
  brand: varchar("brand"),
  sku: varchar("sku").unique().notNull(), // stock keeping unit
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),
  costPrice: decimal("cost_price", { precision: 10, scale: 2 }).notNull(),
  stock: integer("stock").default(0),
  lowStockThreshold: integer("low_stock_threshold").default(5),
  images: jsonb("images").$type<string[]>().default([]),
  weight: decimal("weight", { precision: 8, scale: 2 }), // in kg
  dimensions: jsonb("dimensions").$type<{ length: number; width: number; height: number }>(),
  status: varchar("status").notNull().default("active"), // active, inactive, discontinued
  tags: jsonb("tags").$type<string[]>().default([]),
  shopId: varchar("shop_id").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Stock movements table
export const stockMovements = pgTable("stock_movements", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  productId: varchar("product_id").notNull(),
  type: varchar("type").notNull(), // in, out, adjustment
  quantity: integer("quantity").notNull(),
  reason: varchar("reason").notNull(), // purchase, sale, return, damaged, adjustment
  referenceId: varchar("reference_id"), // order ID, purchase ID, etc.
  notes: text("notes"),
  performedBy: varchar("performed_by").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
});

// Orders table
export const shopOrders = pgTable("shop_orders", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orderNumber: varchar("order_number").unique().notNull(),
  customerId: varchar("customer_id"),
  customerName: varchar("customer_name").notNull(),
  customerEmail: varchar("customer_email").notNull(),
  customerPhone: varchar("customer_phone"),
  shippingAddress: jsonb("shipping_address").$type<{
    street: string;
    city: string;
    province: string;
    postalCode: string;
    country: string;
  }>().notNull(),
  billingAddress: jsonb("billing_address").$type<{
    street: string;
    city: string;
    province: string;
    postalCode: string;
    country: string;
  }>(),
  items: jsonb("items").$type<{
    productId: string;
    productName: string;
    sku: string;
    quantity: number;
    unitPrice: number;
    totalPrice: number;
  }[]>().notNull(),
  subtotal: decimal("subtotal", { precision: 10, scale: 2 }).notNull(),
  shippingFee: decimal("shipping_fee", { precision: 10, scale: 2 }).default("0"),
  tax: decimal("tax", { precision: 10, scale: 2 }).default("0"),
  total: decimal("total", { precision: 10, scale: 2 }).notNull(),
  paymentStatus: varchar("payment_status").notNull().default("pending"), // pending, paid, failed, refunded
  paymentMethod: varchar("payment_method"), // credit_card, paypal, bank_transfer, cod
  paymentId: varchar("payment_id"),
  orderStatus: varchar("order_status").notNull().default("pending"), // pending, confirmed, processing, shipped, delivered, cancelled
  shippingStatus: varchar("shipping_status").default("not_shipped"), // not_shipped, preparing, shipped, delivered
  trackingNumber: varchar("tracking_number"),
  shippingProvider: varchar("shipping_provider"), // fedex, ups, dhl, lbc, etc.
  notes: text("notes"),
  shopId: varchar("shop_id").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Shop analytics/stats table
export const shopStats = pgTable("shop_stats", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  shopId: varchar("shop_id").notNull().unique(),
  totalProducts: integer("total_products").default(0),
  totalOrders: integer("total_orders").default(0),
  totalRevenue: decimal("total_revenue", { precision: 15, scale: 2 }).default("0"),
  monthlyRevenue: decimal("monthly_revenue", { precision: 12, scale: 2 }).default("0"),
  totalCustomers: integer("total_customers").default(0),
  averageOrderValue: decimal("average_order_value", { precision: 10, scale: 2 }).default("0"),
  totalSales: integer("total_sales").default(0),
  monthlySales: integer("monthly_sales").default(0),
  lowStockProducts: integer("low_stock_products").default(0),
  outOfStockProducts: integer("out_of_stock_products").default(0),
  pendingOrders: integer("pending_orders").default(0),
  shippingOrders: integer("shipping_orders").default(0),
  lastUpdated: timestamp("last_updated").defaultNow(),
});

// Type definitions
export type Product = typeof products.$inferSelect;
export type InsertProduct = typeof products.$inferInsert;
export type StockMovement = typeof stockMovements.$inferSelect;
export type InsertStockMovement = typeof stockMovements.$inferInsert;
export type ShopOrder = typeof shopOrders.$inferSelect;
export type InsertShopOrder = typeof shopOrders.$inferInsert;
export type ShopStats = typeof shopStats.$inferSelect;

// Zod schemas for validation
export const insertProductSchema = createInsertSchema(products).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertStockMovementSchema = createInsertSchema(stockMovements).omit({
  id: true,
  createdAt: true,
});

export const insertShopOrderSchema = createInsertSchema(shopOrders).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type InsertProductData = z.infer<typeof insertProductSchema>;
export type InsertStockMovementData = z.infer<typeof insertStockMovementSchema>;
export type InsertShopOrderData = z.infer<typeof insertShopOrderSchema>;

