import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';
import { Plus, Edit, X } from 'lucide-react';
import { statusInfo, getAvailableTransitions, validateStatusTransition, type TripStatus, type UserRole } from '@shared/status-transitions';

// Form validation schema
const tourFormSchema = z.object({
  title: z.string().min(1, "Title is required"),
  description: z.string().optional(),
  category: z.array(z.string()).min(1, "At least one category is required"),
  price: z.string().min(1, "Price is required"),
  currency: z.string().default("PHP"),
  hostName: z.string().min(1, "Host name is required"),
  hostAvatar: z.string().optional(),
  hostBio: z.string().optional(),
  maxParticipants: z.number().min(1, "Must have at least 1 participant"),
  duration: z.string().optional(),
  location: z.string().optional(),
  heroImage: z.string().optional(),
  featured: z.boolean().default(false),
  status: z.enum(["pending_approval", "active", "ongoing", "completed", "declined", "for_revision", "for_reevaluation"]).default("pending_approval"),
  meetingPlace: z.string().optional(),
  startAt: z.string().optional(),
  endAt: z.string().optional(),
  adminNotes: z.string().optional(),

  // Tab content fields
  inclusions: z.string().optional(),
  thingsToBring: z.string().optional(),
  reminders: z.string().optional(),
  cancellationPolicy: z.string().optional()
});

type TourFormData = z.infer<typeof tourFormSchema>;

interface AdminTourFormProps {
  tour?: any; // Tour data for editing
  isEdit?: boolean;
  onClose?: () => void;
  isOpen?: boolean; // External dialog control
}

export const AdminTourForm = ({ tour, isEdit = false, onClose, isOpen: externalIsOpen }: AdminTourFormProps) => {
  const [internalIsOpen, setInternalIsOpen] = useState(false);

  // Use external control if provided, otherwise use internal state
  const isOpen = externalIsOpen !== undefined ? externalIsOpen : internalIsOpen;

  const handleClose = () => {
    if (externalIsOpen !== undefined) {
      // Externally controlled - call onClose prop
      onClose?.();
    } else {
      // Internally controlled - use internal state
      setInternalIsOpen(false);
    }
  };
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const form = useForm<TourFormData>({
    resolver: zodResolver(tourFormSchema),
    defaultValues: {
      title: tour?.title || '',
      description: tour?.description || '',
      category: tour?.category ? (Array.isArray(tour.category) ? tour.category : JSON.parse(tour.category)) : [],
      price: tour?.price?.toString() || '',
      currency: tour?.currency || 'PHP',
      hostName: tour?.hostName || '',
      hostAvatar: tour?.hostAvatar || '',
      hostBio: tour?.hostBio || '',
      maxParticipants: tour?.maxParticipants || 1,
      duration: tour?.duration || '',
      location: tour?.location || '',
      heroImage: tour?.heroImage || '',
      featured: tour?.featured || false,
      status: tour?.status || 'pending_approval',
      meetingPlace: tour?.meetingPlace || '',
      startAt: tour?.startAt ? tour.startAt.split('T')[0] : '',
      endAt: tour?.endAt ? tour.endAt.split('T')[0] : '',
      adminNotes: tour?.adminNotes || '',
      inclusions: tour?.inclusions?.join('\n') || '',
      thingsToBring: tour?.thingsToBring?.join('\n') || '',
      reminders: tour?.reminders?.join('\n') || '',
      cancellationPolicy: tour?.cancellationPolicy || ''
    }
  });

  const createTourMutation = useMutation({
    mutationFn: async (data: TourFormData) => {
      const url = isEdit ? `/api/admin/tours/${tour.id}` : '/api/admin/tours';
      const method = isEdit ? 'PUT' : 'POST';
      return apiRequest(method, url, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/tours'] });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/analytics'] });
      toast({
        title: isEdit ? "Tour Updated" : "Tour Created",
        description: `Tour has been ${isEdit ? 'updated' : 'created'} successfully.`,
      });
      handleClose();
      form.reset();
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || `Failed to ${isEdit ? 'update' : 'create'} tour.`,
        variant: "destructive",
      });
    }
  });

  const onSubmit = (data: TourFormData) => {
    // Convert string fields to arrays (split by newlines and filter empty lines)
    const processedData = {
      ...data,
      price: parseFloat(data.price),
      maxParticipants: Number(data.maxParticipants),
      category: JSON.stringify(data.category), // Convert category array to JSON string
      inclusions: data.inclusions ? data.inclusions.split('\n').filter(line => line.trim()) : [],
      thingsToBring: data.thingsToBring ? data.thingsToBring.split('\n').filter(line => line.trim()) : [],
      reminders: data.reminders ? data.reminders.split('\n').filter(line => line.trim()) : [],
      cancellationPolicy: data.cancellationPolicy || '',
      startAt: data.startAt ? new Date(data.startAt).toISOString() : null,
      endAt: data.endAt ? new Date(data.endAt).toISOString() : null,
      adminNotes: data.adminNotes || '',
      lastStatusChange: new Date().toISOString()
    };

    createTourMutation.mutate(processedData as any);
  };

  const categories = [
    "Private", "Joiner", "Meetups", "Mystery", "Events", "Virtual", "Online Quizzes", "Niche Events"
  ];

  // Get all statuses with their UI information
  const statuses = Object.entries(statusInfo).map(([value, info]) => ({
    value: value as TripStatus,
    label: info.label,
    color: info.color,
    description: info.description
  }));

  return (
    <Dialog open={isOpen} onOpenChange={(open) => {
      if (externalIsOpen !== undefined) {
        // Externally controlled - delegate to onClose when closing
        if (!open) handleClose();
      } else {
        // Internally controlled - sync internal state
        setInternalIsOpen(open);
      }
    }}>
      {/* Only show trigger button when not externally controlled */}
      {externalIsOpen === undefined && (
        <DialogTrigger asChild>
          <Button className="bg-[#D4AF37] hover:bg-[#B8941F] text-black">
            {isEdit ? (
              <>
                <Edit className="w-4 h-4 mr-2" />
                Edit Tour
              </>
            ) : (
              <>
                <Plus className="w-4 h-4 mr-2" />
                Add Tour
              </>
            )}
          </Button>
        </DialogTrigger>
      )}
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center justify-between">
            {isEdit ? "Edit Tour" : "Create New Tour"}
            <Button
              variant="ghost"
              size="sm"
              onClick={handleClose}
            >
              <X className="w-4 h-4" />
            </Button>
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
          {/* Basic Information */}
          <Card className="p-4">
            <h3 className="font-medium mb-4">Basic Information</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="title">Tour Title *</Label>
                <Input
                  id="title"
                  {...form.register('title')}
                  placeholder="Amazing Adventure Tour"
                />
                {form.formState.errors.title && (
                  <p className="text-sm text-red-600 mt-1">{form.formState.errors.title.message}</p>
                )}
              </div>

              <div>
                <Label htmlFor="category">Categories *</Label>
                <div className="space-y-2">
                  <div className="flex flex-wrap gap-2 mb-2">
                    {form.watch('category').map((categoryValue: string) => {
                      const categoryLabel = categories.find(cat => cat.toLowerCase().replace(/\s+/g, '-') === categoryValue) || categoryValue;
                      return (
                        <Badge 
                          key={categoryValue}
                          variant="secondary" 
                          className="bg-[#D4AF37] text-black hover:bg-[#B8941F] cursor-pointer"
                          onClick={() => {
                            const currentCategories = form.watch('category');
                            form.setValue('category', currentCategories.filter((cat: string) => cat !== categoryValue));
                          }}
                        >
                          {categoryLabel}
                          <X className="w-3 h-3 ml-1" />
                        </Badge>
                      );
                    })}
                  </div>
                  <Select
                    value=""
                    onValueChange={(value) => {
                      const currentCategories = form.watch('category');
                      if (!currentCategories.includes(value)) {
                        form.setValue('category', [...currentCategories, value]);
                      }
                    }}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Add categories" />
                    </SelectTrigger>
                    <SelectContent>
                      {categories
                        .filter(category => !form.watch('category').includes(category.toLowerCase().replace(/\s+/g, '-')))
                        .map((category) => (
