      {isAdmin && (
        <AdminAudioModal
          isOpen={showAudioModal}
          onClose={() => setShowAudioModal(false)}
          tripData={{
            title: trip.title,
            duration: trip.duration,
            price: trip.price,
            category: trip.category,
            host: {
              name: trip.host?.name || '',
              bio: trip.host?.bio || ''
            },
            itinerary: trip.itinerary || [],
            meetingPlace: trip.meetingPlace
          }}
        />
      )}
    </div>
  );
};

