import { useState, useEffect } from "react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { NavigationBar } from "@/components/NavigationBar";
import { MapPin, Clock, Users, Star, ArrowLeft, Search } from "lucide-react";

interface Tour {
  id: string;
  title: string;
  location: string;
  destination: string;
  price: string;
  image: string;
  category: string;
  slug: string;
  duration: string;
  participants: number;
  rating?: number;
  description: string;
}

export const SearchResultsPage = (): JSX.Element => {
  const [location, setLocation] = useLocation();
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<Tour[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [allTours, setAllTours] = useState<Tour[]>([]);
  const [toursLoaded, setToursLoaded] = useState(false);
  const [urlSearch, setUrlSearch] = useState(window.location.search);

  // Fetch all tours from the database on mount
  useEffect(() => {
    const fetchTours = async () => {
      try {
        console.log('Fetching tours from /api/trips...');
        const response = await fetch('/api/trips?limit=100');
        console.log('Response status:', response.status);
        if (response.ok) {
          const tours = await response.json();
          console.log('Fetched tours:', tours.length);
          // Transform database tours to match Tour interface
          const transformedTours = tours.map((tour: any) => {
            // Handle category - can be array, JSON string, or plain string
            let categories: string[] = [];
            if (Array.isArray(tour.category)) {
              categories = tour.category;
            } else if (typeof tour.category === 'string') {
              if (tour.category.startsWith('[')) {
                // It's a JSON array string
                try {
                  categories = JSON.parse(tour.category);
                } catch (e) {
                  categories = [tour.category];
                }
              } else {
                // It's a plain string
                categories = [tour.category];
              }
            }

            return {
              id: tour.id,
              title: tour.title,
              location: tour.location || 'Philippines',
              destination: tour.location || 'Philippines',
              price: `₱${parseFloat(tour.price).toLocaleString()}`,
              image: tour.heroImage || 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=400&h=250&fit=crop',
              category: categories[0] || 'Adventure',
              slug: tour.id,
              duration: tour.duration || 'N/A',
              participants: tour.maxParticipants || 0,
              rating: tour.rating ? parseFloat(tour.rating) : undefined,
              description: tour.description || ''
            };
          });
          console.log('Transformed tours:', transformedTours.length);
          setAllTours(transformedTours);
          setToursLoaded(true);
        } else {
          console.error('Failed to fetch tours:', response.statusText);
          setToursLoaded(true);
        }
      } catch (error) {
        console.error('Error fetching tours:', error);
        setToursLoaded(true);
      }
    };
    fetchTours();
  }, []);

  // Track URL search params changes
  useEffect(() => {
    setUrlSearch(window.location.search);
  }, [location]);

  // Perform search when tours are loaded and query exists
  useEffect(() => {
    const params = new URLSearchParams(urlSearch);
    const query = params.get('q') || '';

    if (toursLoaded && query) {
      console.log('Tours loaded, performing search for:', query);
      setIsLoading(true);

      const results = allTours.filter(tour =>
        tour.title.toLowerCase().includes(query.toLowerCase()) ||
        tour.location.toLowerCase().includes(query.toLowerCase()) ||
        tour.category.toLowerCase().includes(query.toLowerCase()) ||
        tour.description.toLowerCase().includes(query.toLowerCase()) ||
        tour.destination.toLowerCase().includes(query.toLowerCase())
      );

      console.log('Search results found:', results.length);
      setSearchResults(results);
      setSearchQuery(query);
      setIsLoading(false);
    } else if (toursLoaded && !query) {
      setSearchResults([]);
      setIsLoading(false);
    }
  }, [toursLoaded, allTours, urlSearch]);

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, i) => (
      <Star
        key={i}
        className={`w-3 h-3 ${i < Math.floor(rating) ? 'text-yellow-400 fill-current' : 'text-gray-300'}`}
      />
    ));
  };

  return (
    <div className="min-h-screen bg-white">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            {/* Logo */}
            <div className="flex items-center">
              <Link href="/" className="text-2xl font-bold text-black">
                LAKBAY
              </Link>
            </div>

            {/* Navigation with Search */}
            <NavigationBar currentPage="search" />

            {/* User Account */}
            <div className="flex items-center space-x-4">
              <Link href="/login">
                <Button variant="ghost" size="sm" className="prada-button">
                  Login
                </Button>
              </Link>
              <Link href="/signup">
                <Button size="sm" className="prada-button prada-gold-accent">
                  Join Lakbay
                </Button>
              </Link>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Back Button */}
        <div className="mb-6">
          <Button
            variant="ghost"
            onClick={() => setLocation("/")}
            className="flex items-center text-gray-600 hover:text-black"
            data-testid="button-back"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Home
          </Button>
        </div>

        {/* Search Results Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-light text-black mb-2">
            Search Results
          </h1>
          {searchQuery && (
            <p className="text-gray-600">
              {isLoading ? (
                "Searching..."
              ) : (
                `Found ${searchResults.length} ${searchResults.length === 1 ? 'tour' : 'tours'} for "${searchQuery}"`
              )}
            </p>
          )}
        </div>

        {/* Loading State */}
        {isLoading && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="animate-pulse">
                <div className="bg-gray-200 h-48 rounded-lg mb-4"></div>
                <div className="h-4 bg-gray-200 rounded mb-2"></div>
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                <div className="h-4 bg-gray-200 rounded w-1/2"></div>
              </div>
            ))}
          </div>
        )}

        {/* Search Results */}
        {!isLoading && searchResults.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {searchResults.map((tour) => (
              <Card key={tour.id} className="overflow-hidden hover:shadow-lg transition-shadow duration-200">
                <div className="relative">
                  <img
                    src={tour.image}
                    alt={tour.title}
                    className="w-full h-48 object-cover"
                  />
                  <Badge className="absolute top-3 left-3 bg-white text-black">
                    {tour.category}
                  </Badge>
                </div>

                <div className="p-4">
                  <h3 className="font-medium text-lg mb-2 line-clamp-2">
                    {tour.title}
                  </h3>

                  <div className="flex items-center text-gray-600 mb-2">
                    <MapPin className="w-4 h-4 mr-1" />
                    <span className="text-sm">{tour.location}</span>
                  </div>

                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center space-x-4 text-sm text-gray-600">
                      <div className="flex items-center">
                        <Clock className="w-4 h-4 mr-1" />
                        {tour.duration}
                      </div>
                      <div className="flex items-center">
                        <Users className="w-4 h-4 mr-1" />
                        {tour.participants}
                      </div>
                    </div>

                    {tour.rating && (
                      <div className="flex items-center space-x-1">
                        <div className="flex">
                          {renderStars(tour.rating)}
                        </div>
                        <span className="text-sm text-gray-600">
                          {tour.rating}
                        </span>
                      </div>
                    )}
                  </div>

                  <p className="text-sm text-gray-600 mb-4 line-clamp-2">
                    {tour.description}
                  </p>

                  <div className="flex items-center justify-between">
                    <span className="text-xl font-semibold text-black">
                      {tour.price}
                    </span>
                    <Button
                      size="sm"
                      className="bg-black hover:bg-gray-800 text-white"
                      onClick={() => setLocation(`/trip/${tour.slug}`)}
                      data-testid={`button-view-${tour.id}`}
                    >
                      View Details
                    </Button>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        )}

        {/* No Results */}
        {!isLoading && searchQuery && searchResults.length === 0 && (
          <div className="text-center py-12">
            <div className="w-24 h-24 mx-auto mb-6 bg-gray-100 rounded-full flex items-center justify-center">
              <Search className="w-12 h-12 text-gray-400" />
            </div>
            <h2 className="text-2xl font-light text-gray-900 mb-2">
              No tours found
            </h2>
            <p className="text-gray-600 mb-6">
              We couldn't find any tours matching "{searchQuery}". Try searching with different keywords.
            </p>
            <Button
              onClick={() => setLocation("/")}
              className="bg-black hover:bg-gray-800 text-white"
            >
              Browse All Tours
            </Button>
          </div>
        )}

        {/* Empty Search State */}
        {!isLoading && !searchQuery && (
          <div className="text-center py-12">
            <div className="w-24 h-24 mx-auto mb-6 bg-gray-100 rounded-full flex items-center justify-center">
              <Search className="w-12 h-12 text-gray-400" />
            </div>
            <h2 className="text-2xl font-light text-gray-900 mb-2">
              Start your search
            </h2>
            <p className="text-gray-600">
              Use the search bar above to find amazing tours and adventures.
            </p>
          </div>
        )}
      </main>
    </div>
  );
};

